<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();$stats=['users'=>(int)$p->query("SELECT COUNT(*) FROM users")->fetchColumn(),'orders'=>(int)$p->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'pending'=>(int)$p->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'topups'=>(int)$p->query("SELECT COUNT(*) FROM topup_requests WHERE status='pending'")->fetchColumn(),'wallet'=>(int)$p->query("SELECT COALESCE(SUM(wallet_balance),0) FROM users")->fetchColumn()];?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>مدیریت</title><style>body{font-family:Tahoma;background:#f4f8fc;margin:0}.top{background:#fff;padding:18px 5%;display:flex;justify-content:space-between}.wrap{max-width:1150px;margin:30px auto;padding:0 18px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.card{background:#fff;padding:20px;border-radius:18px}.n{font-size:24px;font-weight:bold;margin-top:10px}.links{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.links a{background:#1687d9;color:white;padding:12px 15px;border-radius:10px;text-decoration:none}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}}</style><div class=top><b>کافی‌نت سیداصیل</b><a href=/admin/logout.php>خروج</a></div><div class=wrap><div class=cards><?php foreach([['کاربران',$stats['users']],['سفارش‌ها',$stats['orders']],['در انتظار',$stats['pending']],['شارژهای در انتظار',$stats['topups']],['موجودی کل',money($stats['wallet'])]] as $x):?><div class=card><?=$x[0]?><div class=n><?=$x[1]?></div></div><?php endforeach;?></div><div class=links><a href=/admin/categories.php>📁 دسته‌بندی</a><a href=/admin/services.php>🛍 خدمات</a><a href=/admin/fields.php>🧩 فیلدساز</a><a href=/admin/orders.php>📦 سفارش‌ها</a><a href=/admin/topups.php>💳 شارژ کیف پول</a><a href=/admin/users.php>👥 کاربران</a></div></div>
